_PyDict_Subscript(PyObject *self, PyObject *key)
{
    Py_hash_t hash = _PyObject_HashDictKey(key);
    if (hash == -1) {
        dict_unhashable_type(self, key);
        return NULL;
    }
    return _PyDict_SubscriptKnownHash(self, key, hash);
}

