static PyObject *
list_richcompare_impl(PyObject *v, PyObject *w, int op)
{
    PyListObject *vl, *wl;
    Py_ssize_t i;

    if (!PyList_Check(v) || !PyList_Check(w))
        Py_RETURN_NOTIMPLEMENTED;

    vl = (PyListObject *)v;
    wl = (PyListObject *)w;

    if (Py_SIZE(vl) != Py_SIZE(wl) && (op == Py_EQ || op == Py_NE)) {
        /* Shortcut: if the lengths differ, the lists differ */
        if (op == Py_EQ)
            Py_RETURN_FALSE;
        else
            Py_RETURN_TRUE;
    }

    /* Search for the first index where items are different.
     * We incref vitem/witem before calling PyObject_RichCompareBool, which may
     * release the GIL and allow the list to be mutated in the meantime.
     */
    for (i = 0; i < Py_SIZE(vl) && i < Py_SIZE(wl); i++) {
        PyObject *vitem = vl->ob_item[i];
        PyObject *witem = wl->ob_item[i];
        if (vitem == witem) {
            continue;
        }

        Py_INCREF(vitem);
        Py_INCREF(witem);
        int k = PyObject_RichCompareBool(vitem, witem, Py_EQ);
        if (k < 0) {
            Py_DECREF(vitem);
            Py_DECREF(witem);
            return NULL;
        }
        if (!k) {
            /* We have a differing item -- shortcuts for EQ/NE */
            if (op == Py_EQ) {
                Py_DECREF(vitem);
                Py_DECREF(witem);
                Py_RETURN_FALSE;
            }
            if (op == Py_NE) {
                Py_DECREF(vitem);
                Py_DECREF(witem);
                Py_RETURN_TRUE;
            }
            /* Compare the differing items using the proper operator */
            PyObject *result = PyObject_RichCompare(vitem, witem, op);
            Py_DECREF(vitem);
            Py_DECREF(witem);
            return result;
        }

        Py_DECREF(vitem);
        Py_DECREF(witem);
    }

    /* All compared elements were equal -- compare sizes */
    Py_RETURN_RICHCOMPARE(Py_SIZE(vl), Py_SIZE(wl), op);
}

